import pandas as pd


def run(inputs: dict) -> dict:
    dim_price = inputs["dim_price"].copy()
    stg_price = inputs["stg_price"].copy()
    batch_control = inputs["batch_control"].copy()

    batch_date = batch_control["batch_date"].iloc[0]

    # Build per-product list of version dicts from existing dim_price
    versions_by_product = {}
    for pid, grp in dim_price.groupby("product_id"):
        rows = []
        for _, r in grp.iterrows():
            rows.append({
                "product_id": pid,
                "list_price": r["list_price"],
                "eff_start_date": r["eff_start_date"],
                "eff_end_date": r["eff_end_date"],
            })
        versions_by_product[pid] = rows

    # Determine tail for each product: version with max eff_start_date
    tails = {}
    for pid, rows in versions_by_product.items():
        if len(rows) == 0:
            tails[pid] = None
        else:
            tail = max(rows, key=lambda r: r["eff_start_date"])
            tails[pid] = tail

    # Ensure all products appearing in staging exist in versions_by_product/tails
    for pid in stg_price["product_id"].unique():
        if pid not in versions_by_product:
            versions_by_product[pid] = []
            tails[pid] = None

    # Process staging rows per product, ordered by effective_date ascending
    stg_sorted = stg_price.sort_values(["product_id", "effective_date"], kind="stable")

    for pid, grp in stg_sorted.groupby("product_id", sort=False):
        tail = tails[pid]
        rows = versions_by_product[pid]
        for _, s in grp.iterrows():
            s_price = s["list_price"]
            s_date = s["effective_date"]
            if tail is not None and tail["list_price"] == s_price:
                # unchanged, skip
                continue
            else:
                if tail is not None:
                    tail["eff_end_date"] = s_date
                new_row = {
                    "product_id": pid,
                    "list_price": s_price,
                    "eff_start_date": s_date,
                    "eff_end_date": pd.NaT,
                }
                rows.append(new_row)
                tail = new_row
        tails[pid] = tail
        versions_by_product[pid] = rows

    # Flatten all rows
    all_rows = []
    for pid, rows in versions_by_product.items():
        for r in rows:
            all_rows.append(r)

    out = pd.DataFrame(all_rows, columns=["product_id", "list_price", "eff_start_date", "eff_end_date"])

    if len(out) == 0:
        out["is_current"] = pd.Series(dtype="int64")
    else:
        def compute_is_current(row):
            start = row["eff_start_date"]
            end = row["eff_end_date"]
            if start <= batch_date and (pd.isna(end) or batch_date < end):
                return 1
            return 0

        out["is_current"] = out.apply(compute_is_current, axis=1)

    # Ensure proper dtypes
    out["product_id"] = out["product_id"].astype("int64")
    out["list_price"] = out["list_price"].astype("float64")
    out["eff_start_date"] = pd.to_datetime(out["eff_start_date"])
    out["eff_end_date"] = pd.to_datetime(out["eff_end_date"])
    out["is_current"] = out["is_current"].astype("int64")

    out = out[["product_id", "list_price", "eff_start_date", "eff_end_date", "is_current"]]

    return {"dim_price_out": out}
